(124304, 5823, 806, '<td valign="top">Excellent. Shows what the cyclist must face... and gives an air that he/she is alone in this personal challenge.</td>', 'Excellent. Shows what the cyclist must face... and gives an air that he/she is alone in this personal challenge.', '2002-09-16 20:56:00.000000', NULL, 1),
(124305, 5823, 1543, '<td valign="top">nice shot.</td>', 'nice shot.', '2002-09-16 21:13:00.000000', NULL, 1),
