(124553, 5836, 259, '<td valign="top">very nice</td>', 'very nice', '2002-09-18 21:13:00.000000', NULL, 1),
(124554, 5836, 1856, '<td valign="top">I love the color combo here...beautiful image!  Lisa</td>', 'I love the color combo here...beautiful image!  Lisa', '2002-09-19 11:39:00.000000', NULL, 1),
(124555, 5836, 3112, '<td valign="top">Bird is too far to left, and slightly out of focus.  Good eye though. 6</td>', 'Bird is too far to left, and slightly out of focus.  Good eye though. 6', '2002-09-19 17:37:00.000000', NULL, 1),
(124556, 5836, 1031, '<td valign="top">To my eye it would be stronger cropping off about 1/3 from the right and bottom, leaving the bird and the top three branches. Proportionally more sky and a bigger (more visible) bird that way.</td>', 'To my eye it would be stronger cropping off about 1/3 from the right and bottom, leaving the bird and the top three branches. Proportionally more sky and a bigger (more visible) bird that way.', '2002-09-20 04:58:00.000000', NULL, 1),
(124557, 5836, 3087, '<td valign="top">The colour of the foliage and bird against the vivid sky are very pleasant. The moon as a secondary detail is a nice touch. If other ratios were allowed I''d like to see this with the bottom 1/4 chopped away.<br/>5, Kavey</td>', 'The colour of the foliage and bird against the vivid sky are very pleasant. The moon as a secondary detail is a nice touch. If other ratios were allowed I''d like to see this with the bottom 1/4 chopped away.5, Kavey', '2002-09-20 12:19:00.000000', NULL, 1);
