(125922, 5921, 2667, '<td valign="top">you got it! the negative space is the "wow" of this photo. (10) ~mcmurma</td>', 'you got it! the negative space is the "wow" of this photo. (10) ~mcmurma', '2002-09-16 21:23:00.000000', NULL, 1),
(125923, 5921, 674, '<td valign="top">Composition: 5<br/>Lighting:  good 5,<br/> Appeal: 5, Total Rating 5 Sulamk<br/></td>', 'Composition: 5Lighting:  good 5, Appeal: 5, Total Rating 5 Sulamk', '2002-09-18 02:31:00.000000', NULL, 1),
(125924, 5921, 3732, '<td valign="top">Good</td>', 'Good', '2002-09-19 14:54:00.000000', NULL, 1),
